def covers_from_notes(apps, schema_editor):
    """Imports wrote covers into the note ("The Beatles cover; with X"): copy the original artist to the song."""
    SetlistSong = apps.get_model("events", "SetlistSong")
    Song = apps.get_model("events", "Song")
    for entry in SetlistSong.objects.filter(note__icontains=" cover").select_related("song"):
        for part in (p.strip() for p in entry.note.split(";")):
            if part.lower().endswith(" cover") and len(part) > 6:
                name = part[:-6].strip()[:200]
                if name and not entry.song.cover_of_name:
                    Song.objects.filter(pk=entry.song_id).update(cover_of_name=name)
                break


